class Data {
  Data({
      String? name, 
      String? rollNo, 
      String? className, 
      List<Post>? post,}){
    _name = name;
    _rollNo = rollNo;
    _className = className;
    _post = post;
}

  Data.fromJson(dynamic json) {
    _name = json['name'];
    _rollNo = json['rollNo'];
    _className = json['className'];
    if (json['post'] != null) {
      _post = [];
      json['post'].forEach((v) {
        _post?.add(Post.fromJson(v));
      });
    }
  }
  String? _name;
  String? _rollNo;
  String? _className;
  List<Post>? _post;
Data copyWith({  String? name,
  String? rollNo,
  String? className,
  List<Post>? post,
}) => Data(  name: name ?? _name,
  rollNo: rollNo ?? _rollNo,
  className: className ?? _className,
  post: post ?? _post,
);
  String? get name => _name;
  String? get rollNo => _rollNo;
  String? get className => _className;
  List<Post>? get post => _post;

  Map<String, dynamic> toJson() {
    final map = <String, dynamic>{};
    map['name'] = _name;
    map['rollNo'] = _rollNo;
    map['className'] = _className;
    if (_post != null) {
      map['post'] = _post?.map((v) => v.toJson()).toList();
    }
    return map;
  }

}

